import { test, expect } from '@playwright/test';
import { createApp, passwordHash } from '../../server/app.js';
import { randomUUID } from 'node:crypto';
import { readdirSync, readFileSync } from 'node:fs';
const password = 'Password-Uji-2026!';
const suffix = Date.now() + '-' + Math.random().toString(16).slice(2);
const staffEmail = 'staff-' + suffix + '@example.test',biEmail = 'bi-' + suffix + '@example.test';
const superEmail='super-'+suffix+'@example.test';
test.beforeAll(async () => {
  const { db } = await createApp({ dataDir: new URL('../../data/e2e', import.meta.url).pathname });
  for (const [email, role] of [[staffEmail, 'admin'], [biEmail, 'bi'],[superEmail,'superadmin']]) await db.prepare('INSERT INTO accounts VALUES(?,?,?,?,?,?)').run(randomUUID(), email, 'Akun Uji ' + role, 'Tlogomas', role, await passwordHash(password));const row=await db.prepare('SELECT data FROM state WHERE id=1').get();const state=JSON.parse(row.data);for(const [type,name] of [['komunitas','Tlogomas'],['instansi','Universitas Uji']])if(!state.communities.some(group=>!group.deletedAt&&group.type===type&&group.name===name))state.communities.push({id:randomUUID(),type,name});await db.prepare('UPDATE state SET data=? WHERE id=1').run(JSON.stringify(state));await db.close();
});
async function register(page) {
  const email = 'warga-' + randomUUID() + '@example.test';await page.goto('/warga/');await page.locator('[data-auth="reg"]').click();await page.locator('#aName').fill('Warga Pengujian');await page.locator('#aEmail').fill(email);await page.locator('#aPassword').fill(password);await page.locator('#aLoc').selectOption('Tlogomas');await page.locator('#authForm [type=submit]').click();await expect(page.locator('#scr')).toContainText('Periksa email Anda');const dir = new URL('../../data/e2e/mail-preview/', import.meta.url);const mail = readdirSync(dir).map((file) => JSON.parse(readFileSync(new URL(file, dir), 'utf8'))).find((m) => m.to === email);await page.goto(mail.text.match(/https?:\/\/\S+/)[0]);await expect(page.locator('#profileForm')).toBeVisible();await page.locator('#profileForm [name=originType]').selectOption('komunitas');await page.locator('#profileForm [name=communityId]').selectOption({label:'Tlogomas'});await page.locator('#profileForm [name=whatsapp]').fill('081234567890');await page.locator('#profileForm [name=district]').fill('Lowokwaru');await page.locator('#profileForm [name=city]').fill('Kota Malang');await page.locator('#profileForm [type=submit]').click();await expect(page.locator('.mega')).toBeVisible();return email;
}
async function login(page, email, url = '/warga/') {
  await page.goto(url==='/'?(email.startsWith('bi-')?'/bank-indonesia/':'/petugas/'):url);await page.locator('#aEmail').fill(email);await page.locator('#aPassword').fill(password);await page.locator('#authForm [type=submit]').click();
}
test('email account, uploaded photo, staff review and second-device persistence', async ({ page, browser }) => {
  const errors = [];page.on('pageerror', (e) => errors.push(e.message));const email = await register(page);await page.locator('[data-start]').first().click();await page.locator('[data-tile="tas"]').click();const png = await page.evaluate(() => {const canvas = document.createElement('canvas');canvas.width = 64;canvas.height = 64;canvas.getContext('2d').fillRect(0, 0, 64, 64);return canvas.toDataURL('image/png').split(',')[1];});await page.locator('#fPhoto').setInputFiles({ name: 'proof.png', mimeType: 'image/png', buffer: Buffer.from(png, 'base64') });await page.locator('[data-submit]').click();await expect(page.locator('#scr')).toContainText('sudah tersimpan di server');
  const own = await (await page.request.get('/api/bootstrap')).json(),action = own.acts.at(-1);expect(action.status).toBe('pending');expect(action.photo).toMatch(/^\/api\/photos\//);
  const staffContext = await browser.newContext(),staffPage = await staffContext.newPage();await login(staffPage, staffEmail, '/');await expect(staffPage.locator('#v-admin')).toBeVisible();await staffPage.locator(`[data-ok="${action.id}"]`).click();await expect(staffPage.locator(`[data-ok="${action.id}"]`)).toHaveCount(0);
  await page.reload();await expect(page.locator('#ptsNum')).toHaveText('2');await page.locator('#tabbar [data-go="saya"]').click();await expect(page.locator('#qr canvas')).toBeVisible();await expect(page.locator('#scr')).toContainText('Sudah dicek');
  const second = await browser.newContext(),other = await second.newPage();await login(other, email);await expect(other.locator('#ptsNum')).toHaveText('2');expect(errors).toEqual([]);await staffContext.close();await second.close();
});
