test('team publishes video, PowerPoint, module and plain text for residents', async ({ page, browser }) => {
  const context = await browser.newContext(),admin = await context.newPage();await login(admin, staffEmail, '/');await admin.locator('[data-atab="belajar"]').click();const marker = randomUUID().slice(0, 8);
  await admin.locator('#materialKind').selectOption('video');await admin.locator('#materialForm [name=videoUrl]').fill('not-a-url');await admin.locator('#materialKind').selectOption('text');await expect(admin.locator('#materialForm [name=videoUrl]')).toBeDisabled();
  for (const [kind, file, url] of [['text', null, null], ['video', null, 'https://youtu.be/abcdefghijk'], ['powerpoint', { name: 'uji.pptx', mimeType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation', buffer: Buffer.from('PK\x03\x04' + '0'.repeat(30)) }, null], ['module', { name: 'uji.pdf', mimeType: 'application/pdf', buffer: Buffer.from('%PDF-1.7\nDokumen pengujian transport\n%%EOF') }, null]]) {
    await admin.locator('#materialForm [name=title]').fill(kind + ' ' + marker);await admin.locator('#materialKind').selectOption(kind);await admin.locator('#materialForm [name=body]').fill('Materi belajar dari tim iLitterless. <b>Ini teks biasa.</b>');if (file) await admin.locator('#materialFile').setInputFiles(file);if (url) await admin.locator('#materialForm [name=videoUrl]').fill(url);await admin.locator('#materialForm [type=submit]').click();await expect(admin.locator('#toast')).toContainText('Materi diterbitkan');await expect(admin.locator('#materialForm [name=title]')).toHaveValue('');
  }
  const embedReferrers=[];await page.route('https://www.youtube-nocookie.com/embed/**',async route=>{embedReferrers.push(route.request().headers().referer);await route.fulfill({contentType:'text/html',body:'<!doctype html><title>Player transport test</title>'});});
  await register(page);await page.locator('#tabbar [data-go="belajar"]').click();const own = await (await page.request.get('/api/bootstrap')).json();
  for (const kind of ['text', 'video', 'powerpoint', 'module']) {
    const lesson = own.lessons.find((lesson) => lesson.t === kind + ' ' + marker);await page.locator(`[data-les="${lesson.id}"]`).last().click();await expect(page.locator('[role=dialog]')).toContainText('Ini teks biasa.');
    if (kind === 'text') {await expect(page.locator('[role=dialog] .article-copy')).toContainText('<b>Ini teks biasa.</b>');await page.locator('[data-complete]').click();await expect(page.locator('[role=dialog]')).toHaveCount(0);} else
    {if (kind === 'video'){await expect(page.locator('.lesson-video')).toHaveAttribute('src', /youtube-nocookie/);await expect(page.locator('.lesson-video')).toHaveAttribute('referrerpolicy','strict-origin-when-cross-origin');await expect.poll(()=>embedReferrers.length).toBeGreaterThan(0);expect(embedReferrers.at(-1)).toBe('http://127.0.0.1:5175/');await expect(page.getByRole('link',{name:'Tonton di YouTube'})).toHaveAttribute('href','https://www.youtube.com/watch?v=abcdefghijk');}else {const link = page.locator('[role=dialog] a');expect((await page.request.get(await link.getAttribute('href'))).ok()).toBe(true);}await page.locator('[data-close]').click();}
  }
  expect((await (await page.request.get('/api/bootstrap')).json()).users[0].points).toBe(20);await context.close();
});
